# Declare C standard library functions
extern printf(fmt: string, ...);
extern puts(s: string) ret int;
extern strlen(s: string) ret int;
extern atoi(s: string) ret int;

frame main() ret int {
    # printf - formatted output
    printf("=== FFI Examples ===\n\n");

    # puts - simple string output (adds newline)
    puts("Using puts() from C");

    # strlen - string length
    local msg: string = "Hello, World!";
    local len: int = strlen(msg);
    printf("Length of '%s': %d\n", msg, len);

    # atoi - string to integer
    local numStr: string = "12345";
    local num: int = atoi(numStr);
    printf("atoi('%s') = %d\n", numStr, num);
    printf("Doubled: %d\n", num * 2);

    return 0;
}

extern printf(fmt: string, ...);
extern malloc(size: int) ret *void;
extern free(ptr: *void);
extern memset(ptr: *void, value: int, size: int) ret *void;
extern memcpy(dest: *void, src: *void, size: int) ret *void;

frame main() ret int {
    # Allocate memory
    local size: int = 10;
    local arr: *int = cast<*int>(malloc(size * sizeof<int>()));

    if (arr == nullptr) {
        printf("Allocation failed!\n");
        return 1;
    }

    # Initialize with memset (set all bytes to 0)
    memset(cast<*void>(arr), 0, size * sizeof<int>());

    # Fill array
    loop (local i: int = 0; i < size; i = i + 1) {
        *(arr + i) = i * 10;
    }

    printf("Original array: ");
    loop (local i: int = 0; i < size; i = i + 1) {
        printf("%d ", *(arr + i));
    }
    printf("\n");

    # Copy part of array using memcpy
    local copy: *int = cast<*int>(malloc(5 * sizeof<int>()));
    memcpy(cast<*void>(copy), cast<*void>(arr + 2), 5 * sizeof<int>());

    printf("Copied (elements 2-6): ");
    loop (local i: int = 0; i < 5; i = i + 1) {
        printf("%d ", *(copy + i));
    }
    printf("\n");

    # Clean up
    free(cast<*void>(arr));
    free(cast<*void>(copy));

    return 0;
}

extern printf(fmt: string, ...);

# Math library functions
extern sqrt(x: float) ret float;
extern pow(base: float, exp: float) ret float;
extern sin(x: float) ret float;
extern cos(x: float) ret float;
extern floor(x: float) ret float;
extern ceil(x: float) ret float;
extern abs(x: int) ret int;
extern fabs(x: float) ret float;

frame main() ret int {
    printf("=== Math Library ===\n\n");

    # Square root
    printf("sqrt(16) = %.2f\n", sqrt(16.0));
    printf("sqrt(2) = %.4f\n", sqrt(2.0));

    # Power
    printf("\npow(2, 10) = %.0f\n", pow(2.0, 10.0));
    printf("pow(3, 4) = %.0f\n", pow(3.0, 4.0));

    # Trigonometry (radians)
    local pi: float = 3.14159265;
    printf("\nsin(0) = %.2f\n", sin(0.0));
    printf("cos(0) = %.2f\n", cos(0.0));
    printf("sin(pi/2) = %.2f\n", sin(pi / 2.0));

    # Floor and ceiling
    printf("\nfloor(3.7) = %.1f\n", floor(3.7));
    printf("ceil(3.2) = %.1f\n", ceil(3.2));

    # Absolute value
    printf("\nabs(-42) = %d\n", abs(-42));
    printf("fabs(-3.14) = %.2f\n", fabs(-3.14));

    return 0;
}

extern printf(fmt: string, ...);

# Time functions
extern time(t: *int) ret int;  # time_t is typically int-sized

frame main() ret int {
    printf("=== Time Functions ===\n\n");

    # Get current timestamp
    local timestamp: int = time(nullptr);
    printf("Current timestamp: %d\n", timestamp);

    # Calculate some time values
    local seconds_per_day: int = 60 * 60 * 24;
    local days_since_epoch: int = timestamp / seconds_per_day;

    printf("Seconds since epoch: %d\n", timestamp);
    printf("Days since epoch: %d\n", days_since_epoch);
    printf("Years (approx): %d\n", days_since_epoch / 365);

    return 0;
}

extern printf(fmt: string, ...);
extern getenv(name: string) ret string;

frame main() ret int {
    printf("=== Environment Variables ===\n\n");

    # Get common environment variables
    local home: string = getenv("HOME");
    local user: string = getenv("USER");
    local path: string = getenv("PATH");
    local shell: string = getenv("SHELL");

    if (home != nullptr) {
        printf("HOME: %s\n", home);
    }

    if (user != nullptr) {
        printf("USER: %s\n", user);
    }

    if (shell != nullptr) {
        printf("SHELL: %s\n", shell);
    }

    # Check a variable that might not exist
    local custom: string = getenv("MY_CUSTOM_VAR");
    if (custom == nullptr) {
        printf("\nMY_CUSTOM_VAR is not set\n");
    } else {
        printf("\nMY_CUSTOM_VAR: %s\n", custom);
    }

    return 0;
}

