extern printf(fmt: string, ...);
extern strcmp(a: string, b: string) ret int;

frame areEqual(a: string, b: string) ret bool {
    return strcmp(a, b) == 0;
}

frame main() ret int {
    printf("Comparing strings:\n\n");

    printf("'hello' == 'hello': %d\n", areEqual("hello", "hello"));
    printf("'hello' == 'world': %d\n", areEqual("hello", "world"));
    printf("'abc' == 'ABC': %d\n", areEqual("abc", "ABC"));
    printf("'' == '': %d\n", areEqual("", ""));

    return 0;
}
